package local.pocketchat;
import android.content.*;import android.os.*;import org.json.*;import java.io.*;
public class DesignLaunchTestActivity extends BrandLaunchActivity {
  Intent routed;final JSONArray checks=new JSONArray();void check(String title,boolean value){checks.put(J.obj("name",title,"pass",value));}
  @Override public void startActivity(Intent intent){routed=intent;}@Override public void finish(){}
  @Override public void onCreate(Bundle state){AppSettings.put(this,"brandSeen","false");AppSettings.put(this,"startupDirect","true");ProfileCatalog.get(this).created(1);AppSettings.defaultSlot(this,1);super.onCreate(state);check("Brand screen does not start a hidden chat session",ChatSession.peek()==null);route();check("Default entry routes to selected profile",routed!=null&&routed.getComponent().getClassName().endsWith("ProfileActivity1"));check("Default entry explicitly selects original webpage mode",routed.getBooleanExtra("forceWebMode",false));check("Brand page is shown only until explicitly entered",AppSettings.bool(this,"brandSeen",false));AppSettings.put(this,"startupDirect","false");route();check("Window-list startup remains selectable",routed.getComponent().getClassName().endsWith("WindowHomeActivity"));check("Default window UI setting persists in shared catalog",AppSettings.defaultSlot(this)==1);check("Uncreated window cannot become default",!AppSettings.defaultSlot(this,6));check("Reserved custom fingerprint controls are not active",!FutureFeatures.available(FutureFeatures.Feature.CUSTOM_FINGERPRINT));check("Reserved automation is not active",!FutureFeatures.available(FutureFeatures.Feature.AUTOMATION));check("Native launcher path never constructs browser",ChatSession.peek()==null);AppSettings.defaultSlot(this,0);AppSettings.put(this,"startupDirect","true");AppSettings.put(this,"brandSeen","false");try{J.write(new File(getFilesDir(),"design-launch-results.json"),J.obj("checks",checks).toString(2));}catch(Exception ignored){}}
}
